{
  "packet_id": "H6-T01-2",
  "claim_id": "C043",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C043.component",
    "value": "The selected trial must fit the existing staff.",
    "scope": "Staffing-resource bound on trial selection.",
    "provenance": {
      "refs": [
        {
          "source_id": "P025",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P025 explicitly requires the chosen bounded trial to fit existing staff."
    }
  },
  "signal_basis": {
    "component_id": "C043.signal_basis",
    "value": "A smaller configuration repeatedly reproduces lateness while specified further removals do not; selecting a trial addressing a supported combination remains subject to the existing-staff constraint.",
    "scope": "Reduction evidence and the explicit resource constraint governing subsequent trial selection.",
    "provenance": {
      "refs": [
        {
          "source_id": "P018",
          "role": "SUPPORT"
        },
        {
          "source_id": "P025",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P018 supplies the observed reduction pattern; P025 supplies the trial-selection requirement and staffing bound."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C043.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim states an explicit selection constraint and requires no unresolved empirical relation."
    }
  },
  "rationale": "The claim is licensed as an explicit requirement on trial selection. It does not assert that the reduction signal demonstrates any particular trial's staffing feasibility.",
  "uncertainty": "Whether a particular proposed trial actually fits existing staff is not established by the signal and is outside this claim.",
  "anomalies": []
}
